import PropTypes from "prop-types";
import React from "react";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose, bindActionCreators } from "redux";
import { connect } from "react-redux";
import { Button, ModalManager } from "@traveloka/soya-components";
import OperatorModal from "./OperatorModal";
import StaticLinkText from "./StaticLinkText/StaticLinkText";

import * as style from "./CommonRule.styles";

class Operator extends React.Component {
  constructor(props) {
    super(props);
  }

  handleShowModalChangeOperator = () => {
    const { value } = this.props;
    ModalManager.show({
      title: `Change Operator`,
      body: (
        <OperatorModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleChangeOperatorCondition}
          operator={value}
        />
      ),
      footer: " ",
    });
  };

  handleChangeOperatorCondition = (operator) => {
    if (operator === "And" || operator === "Or") {
      this.changeAndOrCondition(operator);
    } else {
      this.changeNotCondition();
    }
    ModalManager.dismiss();
  };

  changeAndOrCondition(operator) {
    const { actions, componentIndex, index, condition } = this.props;
    const newLeaf =
      condition.leaf.length > 1 ? condition.leaf : [condition.leaf[0], {}];
    const newCondition = { root: operator, leaf: newLeaf };
    actions.editCondition(componentIndex, index, newCondition);
  }

  changeNotCondition() {
    const { actions, componentIndex, index, condition } = this.props;
    const newCondition = { root: "Not", leaf: [condition.leaf[0]] };
    actions.editCondition(componentIndex, index, newCondition);
  }

  handleCancelModalManager = () => {
    ModalManager.dismiss();
  };

  handleNotCondition = () => {
    this.handleOperatorFromNotCondition("Not");
  };

  addOpFromNotCondition(e, operator) {
    const { actions, componentIndex, index, condition } = this.props;
    const newLeaf = operator === "Not" ? [condition] : [condition, {}];
    const newCondition = { root: operator, leaf: newLeaf };
    actions.editCondition(componentIndex, index, newCondition);
  }

  handleOrCondition = () => {
    this.handleOperatorFromNotCondition("Or");
  };

  handleAndCondition = () => {
    this.handleOperatorFromNotCondition("And");
  };

  handleOperatorFromNotCondition = (operator) => {
    const { actions, componentIndex, index, condition } = this.props;
    const newLeaf = operator === "Not" ? [condition] : [condition, {}];
    const newCondition = { root: operator, leaf: newLeaf };
    actions.editCondition(componentIndex, index, newCondition);
  };

  handleRemoveCondition = () => {
    const { value } = this.props;
    const isBinaryOperator =
      value &&
      (value.toUpperCase() === "AND" || value.toUpperCase() === "OR");
    const body = isBinaryOperator
      ? "Are you sure you want to delete this operator? The item directly above it will be removed and the rest of the conditions will be kept."
      : "Are you sure you want to delete this operator? Its branch will be kept.";
    ModalManager.show({
      title: `Delete Operator`,
      type: "default",
      body,
      footer: (
        <div>
          <Button variant="link" onClick={() => ModalManager.dismiss()}>
            Cancel
          </Button>
          <Button variant="blue" onClick={() => this.handleConfirmRemove()}>
            Proceed
          </Button>
        </div>
      ),
    });
  };

  handleConfirmRemove = () => {
    const { componentIndex, index, actions } = this.props;
    actions.removeOperator(componentIndex, index);
    ModalManager.dismiss();
  };

  render() {
    const { value, margin } = this.props;
    return (
      <div className={style.conditionRow} style={{ marginLeft: margin }}>
        <StaticLinkText
          text={value}
          onClick={this.handleShowModalChangeOperator}
          color="#79d1aa"
        />
        <div className={style.operatorGroup}>
          {value === "Not" ? (
            <div style={{ display: "inline" }}>
              <StaticLinkText
                text="NOT"
                onClick={(e) => this.addOpFromNotCondition(e, "Not")}
              />
              <StaticLinkText
                text="OR"
                onClick={(e) => this.addOpFromNotCondition(e, "Or")}
              />
              <StaticLinkText
                text="AND"
                onClick={(e) => this.addOpFromNotCondition(e, "And")}
              />
            </div>
          ) : null}
          <StaticLinkText
            text="Remove"
            color="#F44336"
            onClick={this.handleRemoveCondition}
          />
        </div>
      </div>
    );
  }
}

Operator.propTypes = {
  componentIndex: PropTypes.number.isRequired,
  index: PropTypes.number.isRequired,
  margin: PropTypes.number.isRequired,
  value: PropTypes.string.isRequired,
  actions: PropTypes.object.isRequired,
  condition: PropTypes.object.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

const mapDispatchToProps = (dispatch, ownProps) => ({
  actions: bindActionCreators(commonRulesMapDisToProps, dispatch),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, mapDispatchToProps)
)(Operator);
